preConditionHook:
// HEAD AND SHOULDERS, the named Brooks setup: a three-push pattern whose
// MIDDLE push is the most extreme and whose two outer pushes are roughly
// equal. Occurrence 1 is the right shoulder, 2 the head, 3 the left shoulder.
// The TOP is the sell setup, so it is this rule's SHORT side; the inverted
// bottom is the LONG.
//
// NOT ThreePushPattern at a parameter. Its test is MONOTONE -- each push
// beyond the last, hiPx1 > hiPx2 > hiPx3 -- and this one is PEAKED, hiPx2
// above BOTH neighbours, which no shapeMode selects: the two fire on
// different bars, and hiPx2 > hiPx1 is the exact contradiction of
// ThreePushPattern's first term. Brooks describes it as a wedge whose third
// push fails to surpass the second, and Brian would want it tested as the
// book states it.
//
// THE SYMMETRY TOLERANCE is the tick-sized quantity that held the rule for
// the tick list: the shoulders are 'roughly equal', mechanized as their
// difference being within shoulderSymmetryTicks ticks, std::fabs of the
// difference against the margin (EL AbsValue, ACCEPTED). Raise it and the
// rule degrades toward 'any peaked three-push'; at 0 it demands the two
// shoulders print the same price exactly.
//
// THE NECKLINE IS NOT IN THIS RULE -- it is HeadAndShouldersNecklineBreakout,
// which inlines this same pattern and adds the line through the two pullback
// extremes. R12-04's head-and-shoulders CONTINUATION variant is this shape
// plus a double top or bottom around the right shoulder, which is its own
// pane.
//
// THE PIVOT SCAN IS INLINED from ThreePushPattern rather than reaching into
// SwingHigh.json -- rules in this corpus never reference each other, and the
// register lists Occurrence 3 and above as UNMEASURED while the left shoulder
// IS occurrence 3. Measured pivot rule (EL_Swing_Probe.txt /
// el_swing_output1.txt, @ES 60 min): at-or-beyond the swingStrength OLDER
// bars, STRICTLY beyond the swingStrength NEWER ones (bars-ago indexing makes
// the smaller index the newer bar, so the strict half is the k < j loop,
// el_gt/el_lt, and the at-or-beyond half the k > j loop, el_ge/el_le);
// confirmation lag exactly swingStrength bars, hence j from swingStrength;
// candidate offsets 0..Length-1 inclusive, so the deepest bar touched is
// lookbackBars - 1 + swingStrength; the comparisons carry the 2.22e-12
// relational tolerance; -1 SENTINEL on the prices, every use gated on the
// count reaching 3; the low side's tie sense is the mirror of the measured
// high-side rule. No WFSafe_SwingHigh exists, so plain EL governs, and no
// early break is used -- Break is not a registered EasyLanguage word and the
// twins stay statement for statement.
//
// The tick is ctx.MinMove() / ctx.PriceScale(), division-first, both VERIFIED
// and per-symbol constant for the run.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration is a
// redefinition when this rule is placed twice in one strategy. Every one is
// fully assigned each bar before it is read.
tickSize = ctx.MinMove() / ctx.PriceScale();
pivS = (int)swingStrength;
pivW = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
hsTop = (nHiPiv == 3) && el_gt(hiPx2, hiPx3) && el_gt(hiPx2, hiPx1) && el_le(std::fabs(hiPx3 - hiPx1), shoulderSymmetryTicks * tickSize);
hsBottom = (nLoPiv == 3) && el_lt(loPx2, loPx3) && el_lt(loPx2, loPx1) && el_le(std::fabs(loPx3 - loPx1), shoulderSymmetryTicks * tickSize);
